@extends('layouts.app') @section('title','Performance') @section('page_title','Performance Reviews') @section('content')<div class="card"><h3>Record Review</h3><form method="POST" action="{{ route('hr.performance.store') }}" class="form-grid">@csrf<label>Employee<select name="employee_id">@foreach($employees as $e)<option value="{{ $e->id }}">{{ $e->full_name }}</option>@endforeach</select></label><label>Review date<input type="date" name="review_date" value="{{ today()->toDateString() }}"></label><label>Score / 100<input type="number" step="0.1" min="0" max="100" name="overall_score"></label><label>Strengths<textarea name="strengths"></textarea></label><label>Improvement areas<textarea name="improvement_areas"></textarea></label><label>Goals<textarea name="goals"></textarea></label><button class="btn primary">Save Review</button></form></div><div class="card table-wrap"><table><thead><tr><th>Date</th><th>Employee</th><th>Score</th><th>Strengths</th><th>Goals</th></tr></thead><tbody>@foreach($reviews as $r)<tr><td>{{ $r->review_date->format('d M Y') }}</td><td>{{ $r->employee?->full_name }}</td><td>{{ $r->overall_score }}%</td><td>{{ Str::limit($r->strengths,70) }}</td><td>{{ Str::limit($r->goals,70) }}</td></tr>@endforeach</tbody></table>{{ $reviews->links() }}</div>@endsection